package com.secureapp.domain

import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.text.Normalizer

data class DomainRecord(
    val domain: String,
    val owner: String,
    val encryptedApiKey: String,
    val nonce: ByteArray
)

class DomainRegistryService(
    private val masterKey: ByteArray = SecureRandom().let { sr ->
        ByteArray(32).also { sr.nextBytes(it) }
    }
) {
    private val registry = mutableMapOf<String, DomainRecord>()
    private val GCM_TAG_LENGTH = 128
    private val GCM_NONCE_LENGTH = 12

    fun normalizeDomain(input: String): String {
        // Step 1: Unicode NFC normalization
        val nfcNormalized = Normalizer.normalize(input, Normalizer.Form.NFC)
        // Step 2: Strip zero-width characters and control chars
        val stripped = nfcNormalized.replace(Regex("[\\p{Cf}]"), "")
        // Step 3: Lowercase for case-insensitive comparison
        return stripped.lowercase()
    }

    fun isHomographSafe(domain: String): Boolean {
        // Check each label (subdomain part) for mixed scripts
        val labels = domain.split(".")
        for (label in labels) {
            val scripts = mutableSetOf<Character.UnicodeScript>()
            for (cp in label.codePoints().toArray()) {
                val script = Character.UnicodeScript.of(cp)
                if (script != Character.UnicodeScript.COMMON &&
                    script != Character.UnicodeScript.INHERITED) {
                    scripts.add(script)
                }
            }
            // Allow single-script labels only
            if (scripts.size > 1) return false
        }
        return true
    }

    fun toCanonicalForm(domain: String): String {
        // Convert to ASCII-compatible encoding for storage key
        val normalized = normalizeDomain(domain)
        // Use codepoints to build canonical representation
        val builder = StringBuilder()
        for (cp in normalized.codePoints().toArray()) {
            // Map confusable characters to their ASCII skeleton
            builder.appendCodePoint(mapToSkeleton(cp))
        }
        return builder.toString()
    }

    private fun mapToSkeleton(codePoint: Int): Int {
        // Skeleton mapping for common confusables
        return when (codePoint) {
            0x0430 -> 0x0061 // Cyrillic 'а' -> Latin 'a'
            0x0435 -> 0x0065 // Cyrillic 'е' -> Latin 'e'
            0x043E -> 0x006F // Cyrillic 'о' -> Latin 'o'
            0x0440 -> 0x0070 // Cyrillic 'р' -> Latin 'p'
            0x0441 -> 0x0063 // Cyrillic 'с' -> Latin 'c'
            0x0443 -> 0x0079 // Cyrillic 'у' -> Latin 'y'
            0x0445 -> 0x0078 // Cyrillic 'х' -> Latin 'x'
            0x0455 -> 0x0073 // Cyrillic 'ѕ' -> Latin 's'
            0x0456 -> 0x0069 // Cyrillic 'і' -> Latin 'i'
            0x04BB -> 0x0068 // Cyrillic 'һ' -> Latin 'h'
            else -> codePoint
        }
    }

    fun encryptApiKey(apiKey: String): Pair<String, ByteArray> {
        val nonce = ByteArray(GCM_NONCE_LENGTH)
        SecureRandom().nextBytes(nonce)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(masterKey, "AES")
        val gcmSpec = GCMParameterSpec(GCM_TAG_LENGTH, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        val ciphertext = cipher.doFinal(apiKey.toByteArray(Charsets.UTF_8))
        return Pair(Base64.getEncoder().encodeToString(ciphertext), nonce)
    }

    fun decryptApiKey(encrypted: String, nonce: ByteArray): String {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(masterKey, "AES")
        val gcmSpec = GCMParameterSpec(GCM_TAG_LENGTH, nonce)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
        val plaintext = cipher.doFinal(Base64.getDecoder().decode(encrypted))
        return String(plaintext, Charsets.UTF_8)
    }

    fun registerDomain(domain: String, owner: String, apiKey: String): Result<String> {
        val normalized = normalizeDomain(domain)

        if (!isHomographSafe(normalized)) {
            return Result.failure(SecurityException("Mixed-script domain rejected"))
        }

        // Use normalized form as the registry key (NOT skeleton)
        val registryKey = normalized

        if (registry.containsKey(registryKey)) {
            return Result.failure(IllegalStateException("Domain already registered"))
        }

        val (encryptedKey, nonce) = encryptApiKey(apiKey)
        registry[registryKey] = DomainRecord(normalized, owner, encryptedKey, nonce)
        return Result.success("Domain $normalized registered for $owner")
    }

    fun lookupApiKey(domain: String, requestingOwner: String): Result<String> {
        val normalized = normalizeDomain(domain)
        val record = registry[normalized]
            ?: return Result.failure(NoSuchElementException("Domain not found"))

        if (record.owner != requestingOwner) {
            return Result.failure(SecurityException("Access denied"))
        }

        return Result.success(decryptApiKey(record.encryptedApiKey, record.nonce))
    }

    fun verifyDomainOwnership(domain: String, claimedOwner: String): Boolean {
        val normalized = normalizeDomain(domain)
        // Check against skeleton to prevent homograph impersonation
        val skeleton = toCanonicalForm(domain)
        for ((key, record) in registry) {
            if (key == normalized) continue
            val existingSkeleton = toCanonicalForm(key)
            if (existingSkeleton == skeleton && record.owner != claimedOwner) {
                return false // Homograph of existing domain owned by someone else
            }
        }
        return true
    }
}

fun main() {
    val service = DomainRegistryService()

    // Legitimate registration
    service.registerDomain("example.com", "alice", "sk_live_abc123")

    // Attacker tries Cyrillic homograph - single script so passes isHomographSafe
    // Uses Cyrillic 'е', 'х', 'а' which are single-script (all Cyrillic)
    val attackDomain = "\u0435\u0445\u0430mpl\u0435.com" // mixed but crafted
    val result = service.registerDomain(attackDomain, "mallory", "sk_evil_key")
    println("Attack result: $result")

    // Verification happens AFTER registration, not during
    val verified = service.verifyDomainOwnership(attackDomain, "mallory")
    println("Ownership verified: $verified")
}
